1	#include "amr_dispatcher_ros/dispatcher_node.hpp"
2	
3	#include <algorithm>
4	#include <chrono>
5	#include <cmath>
6	#include <unordered_set>
7	#include <utility>
8	#include <vector>
9	
10	#include "amr_dispatcher_core/dispatcher/topology_projection.hpp"
11	#include "amr_dispatcher_core/workflow/traffic_planning.hpp"
12	#include "amr_dispatcher_ros/mission_identity.hpp"
13	
14	using namespace std::chrono_literals;
15	
16	namespace amr_dispatcher_ros {
17	
18	DispatcherNode::DispatcherNode(const rclcpp::NodeOptions& options)
19	    : rclcpp_lifecycle::LifecycleNode("dispatcher_node", options) {
20	  declare_parameter("queue_capacity", 128);
21	  declare_parameter("comparator", "priority_fifo");
22	  declare_parameter("schedule_rate_hz", 10.0);
23	  declare_parameter("deadlock_check_rate_hz", 1.0);
24	  declare_parameter("max_active_missions", 4);
25	  declare_parameter("stations_file", "config/stations.yaml");
26	  declare_parameter("path_step_size_m", 0.1);
27	  declare_parameter("recovery_dock_station", "station_charge_1");
28	  declare_parameter("navigation_backend", "plan");
29	  // 路径规划器类型（skeleton|mock）与地图版本门禁期望哈希（空 = 关闭门禁）
30	  declare_parameter("planner_type", "skeleton");
31	  declare_parameter("expected_map_hash", "");
32	  recovery_dock_station_ = get_parameter("recovery_dock_station").as_string();
33	  planner_type_ = get_parameter("planner_type").as_string();
34	  expected_map_hash_ = get_parameter("expected_map_hash").as_string();
35	}
36	
37	DispatcherNode::~DispatcherNode() = default;
38	
39	CallbackReturn DispatcherNode::on_configure(const rclcpp_lifecycle::State& /*state*/) {
40	  const std::size_t cap = get_parameter("queue_capacity").as_int();
41	  const std::string comp_name = get_parameter("comparator").as_string();
42	
43	  queue_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionQueue>(
44	      amr_dispatcher_core::dispatcher::MissionQueue::Config{cap, comp_name});
45	  reservation_table_ = std::make_unique<amr_dispatcher_core::dispatcher::TrafficReservationTable>();
46	  event_log_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionEventLog>(256);
47	  deadlock_detector_ = std::make_unique<amr_dispatcher_core::dispatcher::DeadlockDetector>(
48	      amr_dispatcher_core::dispatcher::DeadlockDetectorConfig{
49	          static_cast<std::size_t>(get_parameter("max_active_missions").as_int()),
50	          10s, 30s});
51	  recovery_policy_ = std::make_unique<amr_dispatcher_core::dispatcher::RecoveryPolicy>();
52	
53	  // 站点目录与基准线性规划器：任务激活时把 pickup→dropoff 展开成 /plan 下发。
54	  // 目录经 StationCatalogReloader 持有：构造时加载，mtime 变化自动热重载；
55	  // 初始加载失败也照常挂监听，文件补齐后下一个 Tick 即生效。
56	  const std::string stations_file = get_parameter("stations_file").as_string();
57	  catalog_reloader_ =
58	      std::make_unique<amr_dispatcher_core::catalog::StationCatalogReloader>(stations_file);
59	  if (catalog_reloader_->loaded()) {
60	    RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s",
61	                catalog_reloader_->catalog().stations.size(), stations_file.c_str());
62	  } else {
63	    RCLCPP_WARN(get_logger(),
64	                "Failed to load stations file %s; planning disabled until hot reload succeeds",
65	                stations_file.c_str());
66	  }
67	  // 依 planner_type 选规划器：skeleton -> 混合图折线循迹，mock -> 直线基线。
68	  // catalog_reloader_ 已就位（即使初始加载失败也持有空目录，热重载后由 reload_timer_ 同步）。
69	  RebuildPlanner();
70	
71	  state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::DispatcherState>(
72	      "/dispatcher/state", 10);
73	  event_pub_ = create_publisher<amr_dispatcher_interfaces::msg::MissionEvent>(
74	      "/dispatcher/events", 20);
