27	std::string CurrentIsoTimestamp() {
28	  const auto now = std::chrono::system_clock::now();
29	  const auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(
30	                          now.time_since_epoch()) %
31	                      1000;
32	  const std::time_t timer = std::chrono::system_clock::to_time_t(now);
33	  std::tm tm_buf{};
34	#if defined(_WIN32)
35	  gmtime_s(&tm_buf, &timer);
36	#else
37	  gmtime_r(&timer, &tm_buf);
38	#endif
39	  std::ostringstream ss;
40	  ss << std::put_time(&tm_buf, "%Y-%m-%dT%H:%M:%S") << '.'
41	     << std::setfill('0') << std::setw(3) << millis.count() << 'Z';
42	  return ss.str();
43	}
