104	  bool IsString() const { return type == JsonType::String; }
105	  bool IsNumber() const { return type == JsonType::Number; }
106	  bool IsBool() const { return type == JsonType::Bool; }
107	
108	  const JsonValue* Find(const std::string& key) const {
109	    if (type != JsonType::Object) return nullptr;
110	    auto it = obj_val.find(key);
111	    if (it != obj_val.end()) {
112	      return &it->second;
113	    }
114	    return nullptr;
115	  }
116	};
