118	class MiniJsonParser {
119	 public:
120	  static constexpr size_t kMaxDepth = 64;
121	
122	  explicit MiniJsonParser(std::string_view text) : text_(text), pos_(0), depth_(0) {}
123	
124	  std::optional<JsonValue> Parse() {
125	    SkipWhitespace();
126	    if (pos_ >= text_.size()) {
127	      return std::nullopt;
128	    }
129	    auto val = ParseValue();
130	    if (!val.has_value()) {
131	      return std::nullopt;
132	    }
133	    SkipWhitespace();
134	    if (pos_ != text_.size()) {
135	      return std::nullopt;  // 尾部有多余非空白字符
136	    }
137	    return val;
138	  }
139	
140	 private:
141	  char Peek() const {
142	    if (pos_ < text_.size()) return text_[pos_];
143	    return '\0';
144	  }
145	
146	  char Next() {
147	    if (pos_ < text_.size()) return text_[pos_++];
148	    return '\0';
149	  }
150	
151	  void SkipWhitespace() {
152	    while (pos_ < text_.size()) {
153	      const char c = text_[pos_];
154	      if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
155	        ++pos_;
156	      } else {
157	        break;
158	      }
159	    }
160	  }
161	
162	  std::optional<JsonValue> ParseValue() {
163	    SkipWhitespace();
164	    if (pos_ >= text_.size()) return std::nullopt;
165	    char c = Peek();
166	    if (c == '{') return ParseObject();
167	    if (c == '[') return ParseArray();
168	    if (c == '"') return ParseString();
169	    if (c == 't' || c == 'f') return ParseBool();
170	    if (c == 'n') return ParseNull();
171	    if (c == '-' || (c >= '0' && c <= '9')) return ParseNumber();
172	    return std::nullopt;
173	  }
174	
175	  std::optional<JsonValue> ParseObject() {
176	    if (Next() != '{') return std::nullopt;
177	    if (depth_ >= kMaxDepth) return std::nullopt;
178	    ++depth_;
179	    struct ScopeExit {
180	      size_t& d;
181	      ~ScopeExit() { --d; }
182	    } guard{depth_};
183	
184	    JsonValue val;
185	    val.type = JsonType::Object;
186	    SkipWhitespace();
187	    if (Peek() == '}') {
188	      Next();
189	      return val;
190	    }
191	    while (pos_ < text_.size()) {
192	      SkipWhitespace();
193	      if (Peek() != '"') return std::nullopt;
194	      auto key_val = ParseString();
195	      if (!key_val.has_value()) return std::nullopt;
196	      std::string key = key_val->str_val;
197	
198	      SkipWhitespace();
199	      if (Next() != ':') return std::nullopt;
200	
201	      auto member_val = ParseValue();
202	      if (!member_val.has_value()) return std::nullopt;
203	
204	      val.obj_val.emplace(std::move(key), std::move(*member_val));
205	
206	      SkipWhitespace();
207	      char sep = Peek();
208	      if (sep == ',') {
209	        Next();
210	      } else if (sep == '}') {
211	        Next();
212	        return val;
213	      } else {
214	        return std::nullopt;
215	      }
216	    }
217	    return std::nullopt;
218	  }
219	
220	  std::optional<JsonValue> ParseArray() {
221	    if (Next() != '[') return std::nullopt;
222	    if (depth_ >= kMaxDepth) return std::nullopt;
223	    ++depth_;
224	    struct ScopeExit {
225	      size_t& d;
226	      ~ScopeExit() { --d; }
227	    } guard{depth_};
228	
229	    JsonValue val;
230	    val.type = JsonType::Array;
231	    SkipWhitespace();
232	    if (Peek() == ']') {
233	      Next();
234	      return val;
235	    }
236	    while (pos_ < text_.size()) {
237	      auto item = ParseValue();
238	      if (!item.has_value()) return std::nullopt;
239	      val.arr_val.push_back(std::move(*item));
240	
241	      SkipWhitespace();
242	      char sep = Peek();
243	      if (sep == ',') {
244	        Next();
245	      } else if (sep == ']') {
246	        Next();
247	        return val;
248	      } else {
249	        return std::nullopt;
250	      }
251	    }
252	    return std::nullopt;
253	  }
254	
255	  std::optional<JsonValue> ParseString() {
256	    if (Next() != '"') return std::nullopt;
257	    std::string s;
258	    while (pos_ < text_.size()) {
259	      char c = Next();
260	      if (c == '"') {
261	        JsonValue v;
262	        v.type = JsonType::String;
263	        v.str_val = std::move(s);
264	        return v;
265	      }
266	      if (c == '\\') {
267	        if (pos_ >= text_.size()) return std::nullopt;
268	        char esc = Next();
269	        switch (esc) {
270	          case '"':
271	            s += '"';
272	            break;
273	          case '\\':
274	            s += '\\';
275	            break;
276	          case '/':
277	            s += '/';
278	            break;
279	          case 'b':
280	            s += '\b';
281	            break;
282	          case 'f':
283	            s += '\f';
284	            break;
285	          case 'n':
286	            s += '\n';
287	            break;
288	          case 'r':
289	            s += '\r';
290	            break;
291	          case 't':
292	            s += '\t';
293	            break;
294	          case 'u': {
295	            // 跳过 4 位 hex，简化处理
296	            if (pos_ + 4 > text_.size()) return std::nullopt;
297	            pos_ += 4;
298	            s += '?';
299	            break;
300	          }
301	          default:
302	            s += esc;
303	            break;
304	        }
305	      } else {
306	        s += c;
307	      }
308	    }
309	    return std::nullopt;
310	  }
311	
312	  std::optional<JsonValue> ParseNumber() {
313	    size_t start = pos_;
314	    if (Peek() == '-') Next();
315	    while (pos_ < text_.size() && (std::isdigit(static_cast<unsigned char>(text_[pos_])) ||
316	                                   text_[pos_] == '.' || text_[pos_] == 'e' ||
317	                                   text_[pos_] == 'E' || text_[pos_] == '+' ||
318	                                   text_[pos_] == '-')) {
319	      Next();
320	    }
321	    std::string sub(text_.substr(start, pos_ - start));
322	    try {
323	      size_t processed = 0;
324	      double d = std::stod(sub, &processed);
325	      if (processed != sub.size() || std::isnan(d) || std::isinf(d)) {
326	        return std::nullopt;
327	      }
328	      JsonValue v;
329	      v.type = JsonType::Number;
330	      v.num_val = d;
331	      return v;
332	    } catch (...) {
333	      return std::nullopt;
334	    }
335	  }
336	
337	  std::optional<JsonValue> ParseBool() {
338	    if (text_.substr(pos_, 4) == "true") {
339	      pos_ += 4;
340	      JsonValue v;
341	      v.type = JsonType::Bool;
342	      v.bool_val = true;
343	      return v;
344	    }
345	    if (text_.substr(pos_, 5) == "false") {
346	      pos_ += 5;
347	      JsonValue v;
348	      v.type = JsonType::Bool;
349	      v.bool_val = false;
350	      return v;
351	    }
352	    return std::nullopt;
353	  }
354	
355	  std::optional<JsonValue> ParseNull() {
356	    if (text_.substr(pos_, 4) == "null") {
357	      pos_ += 4;
358	      JsonValue v;
359	      v.type = JsonType::Null;
360	      return v;
361	    }
362	    return std::nullopt;
363	  }
364	
365	  std::string_view text_;
366	  size_t pos_;
367	  size_t depth_;
368	};
