372	std::string SerializeVda5050Order(const VehicleOrder& order,
373	                                  const std::string& version,
374	                                  const std::string& manufacturer) {
375	  std::ostringstream ss;
376	  const std::string vda_version = (version == "v3") ? "3.0.0" : "2.0.0";
377	  const std::string timestamp = CurrentIsoTimestamp();
378	  const uint64_t header_id = g_header_id.fetch_add(1, std::memory_order_relaxed);
379	
380	  ss << "{";
381	  ss << "\"headerId\":" << header_id << ",";
382	  ss << "\"timestamp\":\"" << timestamp << "\",";
383	  ss << "\"version\":\"" << vda_version << "\",";
384	  ss << "\"manufacturer\":\"" << EscapeJsonString(manufacturer) << "\",";
385	  ss << "\"serialNumber\":\"" << EscapeJsonString(order.vehicle_id) << "\",";
386	  ss << "\"orderId\":\"" << EscapeJsonString(order.order_id) << "\",";
387	  ss << "\"orderUpdateId\":" << order.order_update_id << ",";
388	
389	  // nodes
390	  ss << "\"nodes\":[";
391	  for (size_t i = 0; i < order.nodes.size(); ++i) {
392	    if (i > 0) ss << ",";
393	    const auto& node = order.nodes[i];
394	    ss << "{";
395	    ss << "\"nodeId\":\"" << EscapeJsonString(node.node_id) << "\",";
396	    ss << "\"sequenceId\":" << node.sequence_id << ",";
397	    ss << "\"released\":" << (node.released ? "true" : "false") << ",";
398	    ss << "\"nodePosition\":{";
399	    ss << "\"x\":" << FormatDouble(node.x) << ",";
400	    ss << "\"y\":" << FormatDouble(node.y) << ",";
401	    ss << "\"theta\":" << FormatDouble(node.yaw) << ",";
402	    ss << "\"mapId\":\"map\"";
403	    ss << "},";
404	    ss << "\"actions\":[";
405	    for (size_t a = 0; a < node.actions.size(); ++a) {
406	      if (a > 0) ss << ",";
407	      const auto& act = node.actions[a];
408	      ss << "{";
409	      ss << "\"actionType\":\"" << EscapeJsonString(act.action_type) << "\",";
410	      ss << "\"actionId\":\"" << EscapeJsonString(act.action_id) << "\",";
411	      ss << "\"blockingType\":\"HARD\",";
412	      ss << "\"actionParameters\":[";
413	      size_t p_idx = 0;
414	      for (const auto& [k, v] : act.parameters) {
415	        if (p_idx > 0) ss << ",";
416	        ss << "{\"key\":\"" << EscapeJsonString(k) << "\",\"value\":\""
417	           << EscapeJsonString(v) << "\"}";
418	        ++p_idx;
419	      }
420	      ss << "]";
421	      ss << "}";
422	    }
423	    ss << "]";
424	    ss << "}";
425	  }
426	  ss << "],";
427	
428	  // edges
429	  ss << "\"edges\":[";
430	  for (size_t i = 0; i < order.edges.size(); ++i) {
431	    if (i > 0) ss << ",";
432	    const auto& edge = order.edges[i];
433	    uint32_t edge_seq = static_cast<uint32_t>(i * 2 + 2);
434	    for (const auto& node : order.nodes) {
435	      if (node.node_id == edge.start_node_id) {
436	        edge_seq = node.sequence_id + 1;
437	        break;
438	      }
439	    }
440	    ss << "{";
441	    ss << "\"edgeId\":\"" << EscapeJsonString(edge.edge_id) << "\",";
442	    ss << "\"sequenceId\":" << edge_seq << ",";  // edge sequence id
443	    ss << "\"startNodeId\":\"" << EscapeJsonString(edge.start_node_id) << "\",";
444	    ss << "\"endNodeId\":\"" << EscapeJsonString(edge.end_node_id) << "\",";
445	    ss << "\"released\":" << (edge.released ? "true" : "false") << ",";
446	    ss << "\"maxSpeed\":" << FormatDouble(edge.max_speed) << ",";
447	
448	    // trajectory
449	    ss << "\"trajectory\":{";
450	    ss << "\"degree\":1,";
451	    ss << "\"controlPoints\":[";
452	    for (size_t p = 0; p < edge.polyline.size(); ++p) {
453	      if (p > 0) ss << ",";
454	      ss << "{";
455	      ss << "\"x\":" << FormatDouble(edge.polyline[p].x) << ",";
456	      ss << "\"y\":" << FormatDouble(edge.polyline[p].y) << ",";
457	      ss << "\"theta\":" << FormatDouble(edge.polyline[p].yaw);
458	      ss << "}";
459	    }
460	    ss << "]";
461	    ss << "},";
462	
463	    // actions
464	    ss << "\"actions\":[";
465	    for (size_t a = 0; a < edge.actions.size(); ++a) {
466	      if (a > 0) ss << ",";
467	      const auto& act = edge.actions[a];
468	      ss << "{";
469	      ss << "\"actionType\":\"" << EscapeJsonString(act.action_type) << "\",";
470	      ss << "\"actionId\":\"" << EscapeJsonString(act.action_id) << "\",";
471	      ss << "\"blockingType\":\"HARD\",";
472	      ss << "\"actionParameters\":[";
473	      size_t p_idx = 0;
474	      for (const auto& [k, v] : act.parameters) {
475	        if (p_idx > 0) ss << ",";
476	        ss << "{\"key\":\"" << EscapeJsonString(k) << "\",\"value\":\""
477	           << EscapeJsonString(v) << "\"}";
478	        ++p_idx;
479	      }
480	      ss << "]";
481	      ss << "}";
482	    }
483	    ss << "]";
484	    ss << "}";
485	  }
486	  ss << "]";
487	
488	  ss << "}";
489	  return ss.str();
490	}
