531	std::optional<VehicleStateReport> DeserializeVda5050State(const std::string& json_str) {
532	  if (json_str.empty()) {
533	    return std::nullopt;
534	  }
535	  MiniJsonParser parser(json_str);
536	  auto root = parser.Parse();
537	  if (!root.has_value() || !root->IsObject()) {
538	    return std::nullopt;
539	  }
540	
541	  // 必须字段检查: serialNumber
542	  const auto* serial_val = root->Find("serialNumber");
543	  if (!serial_val || !serial_val->IsString() || serial_val->str_val.empty()) {
544	    return std::nullopt;
545	  }
546	
547	  // agvPosition 必须存在且合法
548	  const auto* pos_val = root->Find("agvPosition");
549	  if (!pos_val || !pos_val->IsObject()) {
550	    return std::nullopt;
551	  }
552	  const auto* x_val = pos_val->Find("x");
553	  const auto* y_val = pos_val->Find("y");
554	  const auto* theta_val = pos_val->Find("theta");
555	  if (!x_val || !x_val->IsNumber() || !y_val || !y_val->IsNumber() ||
556	      !theta_val || !theta_val->IsNumber()) {
557	    return std::nullopt;
558	  }
559	
560	  VehicleStateReport report;
561	  report.vehicle_id = serial_val->str_val;
562	  report.x = x_val->num_val;
563	  report.y = y_val->num_val;
564	  report.yaw = theta_val->num_val;
565	
566	  // orderId
567	  const auto* order_id_val = root->Find("orderId");
568	  if (order_id_val && order_id_val->IsString()) {
569	    report.order_id = order_id_val->str_val;
570	  }
571	
572	  // lastNodeId
573	  const auto* last_node_val = root->Find("lastNodeId");
574	  if (last_node_val && last_node_val->IsString()) {
575	    report.last_node_id = last_node_val->str_val;
576	  }
577	
578	  // lastNodeSequenceId
579	  const auto* last_seq_val = root->Find("lastNodeSequenceId");
580	  if (last_seq_val && last_seq_val->IsNumber()) {
581	    if (last_seq_val->num_val >= 0.0 &&
582	        last_seq_val->num_val <= static_cast<double>(UINT32_MAX)) {
583	      report.last_node_sequence_id = static_cast<uint32_t>(last_seq_val->num_val);
584	    }
585	  }
586	
587	  // batteryState
588	  const auto* battery_val = root->Find("batteryState");
589	  if (battery_val && battery_val->IsObject()) {
590	    const auto* charge_val = battery_val->Find("batteryCharge");
591	    if (charge_val && charge_val->IsNumber()) {
592	      report.battery_percent = charge_val->num_val;
593	    }
594	    const auto* charging_val = battery_val->Find("charging");
595	    if (charging_val && charging_val->IsBool()) {
596	      report.is_charging = charging_val->bool_val;
597	    }
598	  }
599	
600	  // safetyState
601	  const auto* safety_val = root->Find("safetyState");
602	  if (safety_val && safety_val->IsObject()) {
603	    const auto* estop_val = safety_val->Find("eStop");
604	    if (estop_val) {
605	      if (estop_val->IsBool()) {
606	        report.estop_active = estop_val->bool_val;
607	      } else if (estop_val->IsString()) {
608	        // VDA 5050 常见: "none", "autoAck", "manual", "remote"
609	        report.estop_active = (estop_val->str_val != "none" && !estop_val->str_val.empty());
610	      }
611	    }
612	  }
613	
614	  // operatingMode
615	  const auto* mode_val = root->Find("operatingMode");
616	  if (mode_val && mode_val->IsString() && !mode_val->str_val.empty()) {
617	    report.operating_mode = mode_val->str_val;
618	  }
619	
620	  // errors
621	  const auto* errors_val = root->Find("errors");
622	  if (errors_val && errors_val->IsArray()) {
623	    for (const auto& err_item : errors_val->arr_val) {
624	      if (err_item.IsObject()) {
625	        std::string err_type;
626	        std::string err_desc;
627	        const auto* t = err_item.Find("errorType");
628	        if (t && t->IsString()) err_type = t->str_val;
629	        const auto* d = err_item.Find("errorDescription");
630	        if (d && d->IsString()) err_desc = d->str_val;
631	
632	        if (!err_type.empty() && !err_desc.empty()) {
633	          report.active_errors.push_back(err_type + ": " + err_desc);
634	        } else if (!err_type.empty()) {
635	          report.active_errors.push_back(err_type);
636	        } else if (!err_desc.empty()) {
637	          report.active_errors.push_back(err_desc);
638	        }
639	      }
640	    }
641	  }
642	
643	  report.online = true;
644	  report.last_report_time = std::chrono::steady_clock::now();
645	  return report;
646	}
