648	std::optional<std::string> DeserializeVda5050Connection(const std::string& json_str) {
649	  if (json_str.empty()) {
650	    return std::nullopt;
651	  }
652	  MiniJsonParser parser(json_str);
653	  auto root = parser.Parse();
654	  if (!root.has_value() || !root->IsObject()) {
655	    return std::nullopt;
656	  }
657	
658	  const auto* conn_val = root->Find("connectionState");
659	  if (!conn_val || !conn_val->IsString() || conn_val->str_val.empty()) {
660	    return std::nullopt;
661	  }
662	
663	  return conn_val->str_val;
664	}
