void Vda5050GatewayNode::DrainInboundQueue() {
  std::deque<std::pair<std::string, std::string>> batch;
  {
    std::lock_guard<std::mutex> lock(inbound_mutex_);
    batch.swap(inbound_queue_);
  }
  const auto dropped = dropped_messages_.exchange(0);
  if (dropped > 0) {
    RCLCPP_WARN(get_logger(), "入站队列溢出丢弃 %zu 条 MQTT 消息（提高 drain频率或检查负载）", dropped);
  }
  for (const auto& [topic, payload] : batch) {
    const InboundTopic parsed = ParseInboundTopic(topic);
    if (!parsed.valid) {
      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "无法解析 MQTT Topic: %s", topic.c_str());
      continue;
    }
    if (parsed.vehicle_id == serial_number_) continue;  // 网关自身 connection 心跳不回环
    VehicleEndpoints& ep = EnsureVehicle(parsed.vehicle_id, parsed.manufacturer);
    if (parsed.leaf == "state") {
      HandleStateMessage(parsed.vehicle_id, payload, ep);
    } else {
      HandleConnectionMessage(parsed.vehicle_id, payload, ep);
    }
  }
}
