      "车辆 %s 连接断开 (MQTT LWT CONNECTIONBROKEN)：发布 /fleet/%s/online=false。"
      "安全铁律（Spec §3/§5）：网关绝不释放任何路权锁——锁保留与逐段释放归调度核心 (Task 5)",
      vehicle_id.c_str(), vehicle_id.c_str());
  }
  if (!ep.online_pub) return;
  const bool online = (*connection == "ONLINE");
  ep.online = online;
  std_msgs::msg::Bool m; m.data = online;
