  InboundTopic out;
  std::vector<std::string> parts;
  size_t start = 0;
  while (start <= topic.size()) {
    size_t pos = topic.find('/', start);
    if (pos == std::string::npos) { parts.push_back(topic.substr(start)); break; }
    parts.push_back(topic.substr(start, pos - start));
