  if (parts[4] != "state" && parts[4] != "connection") return out;
  if (parts[2].empty() || parts[3].empty()) return out;
  out.valid = true;
  out.manufacturer = parts[2];
  out.vehicle_id = parts[3];
  out.leaf = parts[4];
  return out;
}
