int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared<amr_dispatcher_ros::Vda5050GatewayNode>();
  rclcpp::spin(node);
  rclcpp::shutdown();
  return 0;
}

