          .will(mqtt::will_options(lwt_topic, lwt_payload, lwt_qos, true /*retained*/));
      client_->connect(builder.finalize())->wait();
      for (const auto& filter : sub_filters) {
        client_->subscribe(filter, sub_qos)->wait();
      }
