91	// MqttClientWrapper：Eclipse Paho MQTT C++ 的最小封装。
92	// MQTT 类型与线程完全隔离在本 TU，ROS 层只见 topic/string。
93	//
94	// 线程安全设计（防死锁）：Paho 的 receiveThread 既处理 SUBACK 等 token 应答，
95	// 也派发消息回调。因此消息回调绝不能阻塞在任何被跨阻塞调用持有的锁上，
96	// 否则会出现「回调等锁 <-> wait() 等 SUBACK」死锁。故：
97	// - handler_mutex_ 只在拷贝/清空 handler_ 的瞬间持有（微秒级）；
98	// - client_ 只被执行器线程访问（Connect/Publish/Disconnect 均在执行器线程），无需加锁；
99	// - Disconnect 先清空 handler（回调变 no-op），再用 in_flight 计数器 + 条件变量
100	//   等待在途回调退出，最后销毁 client（防止析构期回调触碰已释放的节点成员）。
101	// ============================================================
102	class MqttClientWrapper {
103	 public:
104	  using MessageHandler = std::function<void(const std::string& topic, const std::string& payload)>;
105	
106	  ~MqttClientWrapper() { Disconnect(); }
107	
108	  MqttClientWrapper(const MqttClientWrapper&) = delete;
109	  MqttClientWrapper& operator=(const MqttClientWrapper&) = delete;
110	
111	  /// 建立连接并订阅主题。成功后启用 automatic_reconnect 自动重连；
112	  /// 失败返回 false 并销毁半成品客户端（由调用方定时重试重建）。
113	  bool Connect(const std::string& broker_uri, const std::string& client_id,
114	               const std::vector<std::string>& sub_filters, int sub_qos,
115	               const std::string& lwt_topic, const std::string& lwt_payload, int lwt_qos,
116	               MessageHandler handler, std::string* error) {
117	    {
118	      std::lock_guard<std::mutex> lock(handler_mutex_);
119	      handler_ = std::move(handler);
120	    }
121	    QuiesceCallbacks();  // 等待旧 client 的在途回调退出后再销毁
122	    DestroyClient();
123	    try {
124	      client_ = std::make_unique<mqtt::async_client>(broker_uri, client_id);
125	      client_->set_message_callback([this](mqtt::const_message_ptr msg) {
126	        in_flight_.fetch_add(1, std::memory_order_acq_rel);
127	        MessageHandler handler;
128	        {
129	          std::lock_guard<std::mutex> lock(handler_mutex_);
130	          handler = handler_;
131	        }
132	        if (handler && msg) {
133	          handler(msg->get_topic(), msg->to_string());
134	        }
135	        if (in_flight_.fetch_sub(1, std::memory_order_acq_rel) == 1) {
136	          std::lock_guard<std::mutex> lock(done_mutex_);
137	          done_cv_.notify_all();
138	        }
139	      });
140	      mqtt::connect_options_builder builder;
141	      builder.clean_session(true)
142	          .automatic_reconnect(std::chrono::seconds(1), std::chrono::seconds(60))
143	          .connect_timeout(std::chrono::seconds(5))
144	          .keep_alive_interval(std::chrono::seconds(15))
145	          .will(mqtt::will_options(lwt_topic, lwt_payload, lwt_qos, true /*retained*/));
146	      if (!client_->connect(builder.finalize())->wait_for(std::chrono::seconds(10))) {
147	        if (error != nullptr) *error = "连接超时";
148	        DestroyClient();
149	        return false;
150	      }
151	      for (const auto& filter : sub_filters) {
152	        if (!client_->subscribe(filter, sub_qos)->wait_for(std::chrono::seconds(5))) {
153	          if (error != nullptr) *error = "订阅超时: " + filter;
154	          DestroyClient();
155	          return false;
156	        }
157	      }
158	      connected_once_.store(true);
159	      return true;
160	    } catch (const std::exception& e) {
161	      if (error != nullptr) *error = e.what();
162	      DestroyClient();
163	      return false;
164	    }
165	  }
166	
167	  /// 发布消息。未连接时快速失败（返回 false），绝不阻塞执行器线程。
168	  /// 仅允许在执行器线程调用（与 Connect/Disconnect 串行）。
169	  bool Publish(const std::string& topic, const std::string& payload, int qos, bool retained,
170	               std::string* error) {
171	    if (client_ == nullptr) {
172	      if (error != nullptr) *error = "MQTT 客户端未初始化";
173	      return false;
174	    }
175	    if (!client_->is_connected()) {
176	      if (error != nullptr) *error = "MQTT 未连接";
177	      return false;
178	    }
179	    try {
180	      client_->publish(mqtt::make_message(topic, payload.data(), payload.size(), qos, retained));
181	      return true;
182	    } catch (const std::exception& e) {
183	      if (error != nullptr) *error = e.what();
184	      return false;
185	    }
186	  }
187	
188	  bool HasConnectedOnce() const { return connected_once_.load(); }
189	
190	  /// 优雅断连：不触发 LWT 遗嘱（正常下线不应广播 CONNECTIONBROKEN）。
191	  void Disconnect() {
192	    {
193	      std::lock_guard<std::mutex> lock(handler_mutex_);
194	      handler_ = nullptr;  // 回调屏障：此后的回调拷贝到空 handler 直接 no-op
195	    }
196	    QuiesceCallbacks();
197	    DestroyClient();
198	  }
199	
200	 private:
201	  /// 等待在途消息回调退出（带 1s 上限，防御异常路径挂死）。
202	  void QuiesceCallbacks() {
203	    std::unique_lock<std::mutex> lock(done_mutex_);
204	    done_cv_.wait_for(lock, std::chrono::seconds(1),
205	                      [this] { return in_flight_.load(std::memory_order_acquire) == 0; });
206	  }
207	
208	  /// 仅允许执行器线程调用；调用前须确保无在途回调（见 QuiesceCallbacks）。
209	  void DestroyClient() {
210	    if (client_ == nullptr) return;
211	    try {
212	      if (client_->is_connected()) {
213	        client_->disconnect()->wait_for(std::chrono::seconds(2));
214	      }
215	    } catch (...) {
216	      // 异常路径：连接可能已断，忽略即可
217	    }
218	    client_.reset();
219	  }
220	
221	  // 只保护 handler_ 的拷贝/清空，绝不在阻塞 MQTT 调用期间持有
222	  std::mutex handler_mutex_;
223	  MessageHandler handler_;
224	  std::unique_ptr<mqtt::async_client> client_;
225	
226	  // 在途回调计数（回调线程 <-> Disconnect 屏障）
227	  std::atomic<int> in_flight_{0};
228	  std::mutex done_mutex_;
229	  std::condition_variable done_cv_;
230	
231	  std::atomic<bool> connected_once_{false};
232	};
