242	  declare_parameter("manufacturer", "RobotManufacturer");
243	  declare_parameter("serial_number", "default");
244	  declare_parameter("protocol_version", "v2");
245	  declare_parameter("heartbeat_ms", 5000);
246	
247	  use_vda5050_ = get_parameter("use_vda5050").as_bool();
248	  mqtt_broker_host_ = get_parameter("mqtt_broker_host").as_string();
249	  mqtt_port_ = static_cast<int>(get_parameter("mqtt_port").as_int());
250	  manufacturer_ = get_parameter("manufacturer").as_string();
251	  serial_number_ = get_parameter("serial_number").as_string();
252	  protocol_version_ = get_parameter("protocol_version").as_string();
253	  heartbeat_ms_ = static_cast<int>(get_parameter("heartbeat_ms").as_int());
254	
255	  if (!use_vda5050_) {
256	    RCLCPP_INFO(get_logger(), "VDA 5050 网关未启用 (use_vda5050=false)，节点保持空转 no-op");
257	    return;
258	  }
259	
260	  if (protocol_version_ != "v2" && protocol_version_ != "v3") {
261	    RCLCPP_WARN(get_logger(), "未知 protocol_version '%s'，按 v2 处理", protocol_version_.c_str());
262	    protocol_version_ = "v2";
263	  }
264	  if (mqtt_port_ <= 0 || mqtt_port_ > 65535) {
265	    RCLCPP_WARN(get_logger(), "非法 mqtt_port=%d，回退 1883", mqtt_port_);
266	    mqtt_port_ = 1883;
267	  }
268	  if (manufacturer_.empty()) {
269	    RCLCPP_WARN(get_logger(), "manufacturer 为空，回退 RobotManufacturer");
270	    manufacturer_ = "RobotManufacturer";
271	  }
272	  if (serial_number_.empty()) {
273	    RCLCPP_WARN(get_logger(), "serial_number 为空，回退 default");
274	    serial_number_ = "default";
275	  }
276	  if (heartbeat_ms_ <= 0) {
277	    RCLCPP_WARN(get_logger(), "非法 heartbeat_ms=%d，回退 5000", heartbeat_ms_);
278	    heartbeat_ms_ = 5000;
279	  }
280	
281	  RCLCPP_INFO(get_logger(),
282	              "VDA 5050 网关启用: broker=%s:%d base=%s gateway_identity=%s/%s heartbeat=%dms",
283	              mqtt_broker_host_.c_str(), mqtt_port_, TopicBase().c_str(), manufacturer_.c_str(),
284	              serial_number_.c_str(), heartbeat_ms_);
285	
286	  try {
287	    mqtt_ = std::make_unique<MqttClientWrapper>();
288	    drain_timer_ = create_wall_timer(std::chrono::milliseconds(kDrainPeriodMs),
289	                                     std::bind(&Vda5050GatewayNode::DrainInboundQueue, this));
290	    heartbeat_timer_ = create_wall_timer(
291	        std::chrono::milliseconds(heartbeat_ms_),
292	        std::bind(&Vda5050GatewayNode::PublishGatewayHeartbeat, this));
293	    mqtt_retry_timer_ = create_wall_timer(
294	        std::chrono::milliseconds(kMqttRetryPeriodMs),
295	        std::bind(&Vda5050GatewayNode::TryConnectMqtt, this));
296	    TryConnectMqtt();
297	  } catch (const std::exception& e) {
298	    RCLCPP_ERROR(get_logger(), "MQTT 子系统初始化失败，网关降级为空转: %s", e.what());
299	    if (drain_timer_) drain_timer_->cancel();
300	    if (heartbeat_timer_) heartbeat_timer_->cancel();
301	    if (mqtt_retry_timer_) mqtt_retry_timer_->cancel();
302	    mqtt_.reset();
303	  }
304	}
