306	Vda5050GatewayNode::~Vda5050GatewayNode() {
307	  if (drain_timer_) drain_timer_->cancel();
308	  if (heartbeat_timer_) heartbeat_timer_->cancel();
309	  if (mqtt_retry_timer_) mqtt_retry_timer_->cancel();
310	  // 优雅断连：正常关机不触发 LWT 遗嘱
311	  if (mqtt_) mqtt_->Disconnect();
