314	void Vda5050GatewayNode::TryConnectMqtt() {
315	  if (!mqtt_ || mqtt_->HasConnectedOnce()) {
316	    return;  // 首连成功后由 automatic_reconnect 接管，无需人工重试
317	  }
318	  const std::string uri = "tcp://" + mqtt_broker_host_ + ":" + std::to_string(mqtt_port_);
319	  const std::string client_id = "amr_dispatcher_gateway_" + serial_number_;
320	  const std::vector<std::string> filters = {TopicBase() + "/+/+/state",
321	                                            TopicBase() + "/+/+/connection"};
322	  const std::string lwt_topic = MqttTopic(manufacturer_, serial_number_, "connection");
323	  const std::string lwt_payload = BuildGatewayConnectionJson("CONNECTIONBROKEN");
324	
325	  std::string err;
326	  const bool ok = mqtt_->Connect(
327	      uri, client_id, filters, kQosConnection, lwt_topic, lwt_payload, kQosConnection,
328	      [this](const std::string& topic, const std::string& payload) {
329	        OnMqttMessage(topic, payload);
330	      },
331	      &err);
332	  if (ok) {
333	    RCLCPP_INFO(get_logger(), "MQTT 已连接 %s (client_id=%s, base=%s, LWT=%s)", uri.c_str(),
334	                client_id.c_str(), TopicBase().c_str(), lwt_topic.c_str());
335	  } else {
336	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
337	                         "MQTT 连接失败 %s: %s（首连前每 5s 重试，首连成功后由自动重连接管）",
338	                         uri.c_str(), err.c_str());
339	  }
340	}
