342	void Vda5050GatewayNode::OnMqttMessage(const std::string& topic, std::string payload) {
343	  std::lock_guard<std::mutex> lock(inbound_mutex_);
344	  if (inbound_queue_.size() >= kMaxInboundQueue) {
345	    inbound_queue_.pop_front();
346	    dropped_messages_.fetch_add(1, std::memory_order_relaxed);
347	  }
348	  inbound_queue_.emplace_back(topic, std::move(payload));
349	}
350	
351	void Vda5050GatewayNode::DrainInboundQueue() {
352	  std::deque<std::pair<std::string, std::string>> batch;
353	  {
354	    std::lock_guard<std::mutex> lock(inbound_mutex_);
355	    batch.swap(inbound_queue_);
356	  }
357	  const std::size_t dropped = dropped_messages_.exchange(0, std::memory_order_relaxed);
358	  if (dropped > 0) {
359	    RCLCPP_WARN(get_logger(),
360	                "入站队列溢出，丢弃 %zu 条 MQTT 消息（可调低负载或提高出队频率 kDrainPeriodMs）",
361	                dropped);
362	  }
363	  for (const auto& item : batch) {
364	    const InboundTopic parsed = ParseInboundTopic(item.first);
365	    if (!parsed.valid) {
366	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "忽略无法解析的 MQTT Topic: %s",
367	                           item.first.c_str());
368	      continue;
369	    }
370	    // 网关自身 connection 心跳/LWT 不回环进 ROS 侧
371	    if (parsed.vehicle_id == serial_number_) {
372	      continue;
373	    }
374	    VehicleEndpoints& ep = EnsureVehicle(parsed.vehicle_id, parsed.manufacturer);
375	    if (parsed.leaf == "state") {
376	      HandleStateMessage(parsed.vehicle_id, item.second, ep);
377	    } else {
378	      HandleConnectionMessage(parsed.vehicle_id, item.second, ep);
379	    }
380	  }
381	}
382	
383	void Vda5050GatewayNode::HandleStateMessage(const std::string& vehicle_id,
384	                                            const std::string& payload, VehicleEndpoints& ep) {
385	  if (!ep.state_pub) {
386	    return;  // 非法 vehicle_id 已在 EnsureVehicle 告警，该车无 ROS 端点
387	  }
388	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(payload);
389	  if (!report.has_value()) {
390	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
391	                         "丢弃非法 VDA 5050 state 报文 (vehicle=%s)", vehicle_id.c_str());
392	    return;
393	  }
394	  // 无损透传原始 JSON，Task 5 调度侧可用 DeserializeVda5050State 按需解析
395	  std_msgs::msg::String raw;
396	  raw.data = payload;
397	  ep.state_pub->publish(raw);
398	
399	  geometry_msgs::msg::PoseStamped pose;
400	  pose.header.stamp = now();
401	  pose.header.frame_id = "map";
402	  pose.pose.position.x = report->x;
403	  pose.pose.position.y = report->y;
404	  pose.pose.orientation.z = std::sin(report->yaw * 0.5);
405	  pose.pose.orientation.w = std::cos(report->yaw * 0.5);
406	  ep.pose_pub->publish(pose);
407	
408	  if (!ep.online) {
409	    ep.online = true;
410	    std_msgs::msg::Bool online_msg;
411	    online_msg.data = true;
412	    ep.online_pub->publish(online_msg);
413	  }
414	}
415	
416	void Vda5050GatewayNode::HandleConnectionMessage(const std::string& vehicle_id,
417	                                                 const std::string& payload,
418	                                                 VehicleEndpoints& ep) {
419	  const auto connection = amr_dispatcher_core::fleet::DeserializeVda5050Connection(payload);
420	  if (!connection.has_value()) {
421	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
422	                         "丢弃非法 VDA 5050 connection 报文 (vehicle=%s)", vehicle_id.c_str());
423	    return;
424	  }
425	  if (*connection == "CONNECTIONBROKEN") {
426	    // 安全铁律（Spec §3 / §5.2）：网关绝不释放任何路权锁——
427	    // 仅将 /fleet/{vid}/online 置 false；锁保留与逐段释放由调度核心 (Task 5) 负责。
428	    RCLCPP_WARN(get_logger(),
429	                "车辆 %s MQTT 连接断开 (LWT CONNECTIONBROKEN)：仅发布 /fleet/%s/online=false，"
430	                "绝不释放该车持有的路权锁（锁保留归调度核心 Task 5）",
431	                vehicle_id.c_str(), vehicle_id.c_str());
432	  }
433	  if (!ep.online_pub) {
434	    return;  // 非法 vehicle_id 无 ROS 端点
435	  }
436	  const bool online = (*connection == "ONLINE");
437	  ep.online = online;
438	  std_msgs::msg::Bool online_msg;
439	  online_msg.data = online;
440	  ep.online_pub->publish(online_msg);
441	}
