443	void Vda5050GatewayNode::SendOrderCallback(const std::string& vehicle_id,
444	                                           const std::string& manufacturer,
445	                                           const std_msgs::msg::String::SharedPtr& msg) {
446	  const std::string payload = Trim(msg->data);
447	  if (payload.empty()) {
448	    RCLCPP_WARN(get_logger(), "send_order 收到空报文 (vehicle=%s)，忽略", vehicle_id.c_str());
449	    return;
450	  }
451	  if (payload.front() != '{') {
452	    RCLCPP_WARN(get_logger(),
453	                "send_order 期望 Vda5050OrderBuilder 序列化的 Order JSON，实际开头 '%c' (vehicle=%s)，忽略",
454	                payload.front(), vehicle_id.c_str());
455	    return;
456	  }
457	  const std::string topic = MqttTopic(manufacturer, vehicle_id, "order");
458	  std::string err;
459	  if (mqtt_ && mqtt_->Publish(topic, payload, kQosOrder, false, &err)) {
460	    RCLCPP_INFO(get_logger(), "Order 已下发 MQTT: %s (%zu bytes)", topic.c_str(), payload.size());
461	  } else {
462	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "Order 下发失败 (topic=%s): %s",
463	                         topic.c_str(),
464	                         (mqtt_ == nullptr) ? "MQTT 子系统未启用" : err.c_str());
465	  }
466	}
