468	void Vda5050GatewayNode::InstantActionsCallback(const std::string& vehicle_id,
469	                                                const std::string& manufacturer,
470	                                                const std_msgs::msg::String::SharedPtr& msg) {
471	  const std::string payload = Trim(msg->data);
472	  if (payload.empty()) {
473	    RCLCPP_WARN(get_logger(), "instant_actions 收到空报文 (vehicle=%s)，忽略", vehicle_id.c_str());
474	    return;
475	  }
476	
477	  std::string json;
478	  if (payload.front() == '{') {
479	    json = payload;  // 已是完整 VDA 5050 instantActions JSON，原样透传
480	  } else {
481	    const std::string* canonical = nullptr;
482	    for (const auto& alias : kInstantActionAliases) {
483	      if (payload == alias.alias) {
484	        canonical = &alias.action_type;
485	        break;
486	      }
487	    }
488	    if (canonical == nullptr) {
489	      RCLCPP_WARN(get_logger(),
490	                  "instant_actions 不支持的简单指令 '%s' (vehicle=%s)，"
491	                  "支持: cancelOrder/pause/resume/stopPause，或完整 instantActions JSON",
492	                  payload.c_str(), vehicle_id.c_str());
493	      return;
494	    }
495	    amr_dispatcher_core::fleet::VehicleAction action;
496	    action.action_type = *canonical;
497	    action.action_id = "ia_" + std::to_string(g_instant_action_seq.fetch_add(1));
498	    std::vector<amr_dispatcher_core::fleet::VehicleAction> actions{std::move(action)};
499	    json = amr_dispatcher_core::fleet::SerializeVda5050InstantActions(vehicle_id, actions,
500	                                                                     protocol_version_, manufacturer);
501	  }
502	
503	  const std::string topic = MqttTopic(manufacturer, vehicle_id, "instantActions");
504	  std::string err;
505	  if (mqtt_ && mqtt_->Publish(topic, json, kQosInstantActions, false, &err)) {
506	    RCLCPP_INFO(get_logger(), "InstantActions 已下发 MQTT: %s (%zu bytes)", topic.c_str(),
507	                json.size());
508	  } else {
509	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "InstantActions 下发失败 (topic=%s): %s",
510	                         topic.c_str(),
511	                         (mqtt_ == nullptr) ? "MQTT 子系统未启用" : err.c_str());
512	  }
513	}
