515	void Vda5050GatewayNode::PublishGatewayHeartbeat() {
516	  if (!mqtt_) return;
517	  const std::string topic = MqttTopic(manufacturer_, serial_number_, "connection");
518	  const std::string json = BuildGatewayConnectionJson("ONLINE");
519	  std::string err;
520	  if (!mqtt_->Publish(topic, json, kQosConnection, true /*retained*/, &err)) {
521	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
522	                         "网关 connection 心跳发布失败 (topic=%s): %s", topic.c_str(), err.c_str());
523	  }
524	}
