526	Vda5050GatewayNode::VehicleEndpoints& Vda5050GatewayNode::EnsureVehicle(
527	    const std::string& vehicle_id, const std::string& manufacturer) {
528	  auto it = vehicles_.find(vehicle_id);
529	  if (it != vehicles_.end()) {
530	    return it->second;
531	  }
532	  VehicleEndpoints ep;
533	  ep.manufacturer = manufacturer;  // manufacturer 以首见为准，保证后续原路回发
534	  if (!IsValidVehicleId(vehicle_id)) {
535	    RCLCPP_ERROR(get_logger(),
536	                 "serialNumber '%s' 不是合法 ROS 话题段（须字母或 '_' 开头，仅含字母/数字/'_'），"
537	                 "跳过该车全部 ROS 端点创建（MQTT 订阅解析不受影响）",
538	                 vehicle_id.c_str());
539	  } else {
540	    try {
541	      const std::string base = "/fleet/" + vehicle_id;
542	      ep.state_pub = create_publisher<std_msgs::msg::String>(base + "/state", 10);
543	      ep.pose_pub = create_publisher<geometry_msgs::msg::PoseStamped>(base + "/pose", 10);
544	      ep.online_pub = create_publisher<std_msgs::msg::Bool>(
545	          base + "/online", rclcpp::QoS(rclcpp::KeepLast(1)).transient_local());
546	      ep.send_order_sub = create_subscription<std_msgs::msg::String>(
547	          base + "/send_order", 10,
548	          [this, vehicle_id, manufacturer](const std_msgs::msg::String::SharedPtr m) {
549	            SendOrderCallback(vehicle_id, manufacturer, m);
550	          });
551	      ep.instant_actions_sub = create_subscription<std_msgs::msg::String>(
552	          base + "/instant_actions", 10,
553	          [this, vehicle_id, manufacturer](const std_msgs::msg::String::SharedPtr m) {
554	            InstantActionsCallback(vehicle_id, manufacturer, m);
555	          });
556	      RCLCPP_INFO(get_logger(),
557	                  "发现车辆 %s (manufacturer=%s)，已创建 ROS 端点 %s/{state,pose,online,send_order,instant_actions}",
558	                  vehicle_id.c_str(), manufacturer.c_str(), base.c_str());
559	    } catch (const std::exception& e) {
560	      RCLCPP_ERROR(get_logger(), "创建车辆 %s 的 ROS 端点失败: %s", vehicle_id.c_str(), e.what());
561	      ep = VehicleEndpoints{};  // 部分创建失败则整体放弃，避免半残端点
562	      ep.manufacturer = manufacturer;
563	    }
564	  }
565	  return vehicles_.emplace(vehicle_id, std::move(ep)).first->second;
566	}
