568	Vda5050GatewayNode::InboundTopic Vda5050GatewayNode::ParseInboundTopic(const std::string& topic) {
569	  InboundTopic out;
570	  std::vector<std::string> parts;
571	  std::size_t start = 0;
572	  while (start <= topic.size()) {
573	    const std::size_t pos = topic.find('/', start);
574	    if (pos == std::string::npos) {
575	      parts.push_back(topic.substr(start));
576	      break;
577	    }
578	    parts.push_back(topic.substr(start, pos - start));
579	    start = pos + 1;
580	  }
581	  if (parts.size() != 5) {
582	    return out;  // base/manufacturer/serial/leaf 才是 4 段；此处 topic 含首段，共 5
583	  }
584	  if (parts[4] != "state" && parts[4] != "connection") {
585	    return out;
586	  }
587	  if (parts[2].empty() || parts[3].empty()) {
588	    return out;
589	  }
590	  out.valid = true;
591	  out.manufacturer = parts[2];
592	  out.vehicle_id = parts[3];
593	  out.leaf = parts[4];
594	  return out;
595	}
