597	bool Vda5050GatewayNode::IsValidVehicleId(const std::string& vehicle_id) {
598	  if (vehicle_id.empty()) return false;
599	  const auto ok_first = [](char c) {
600	    return std::isalpha(static_cast<unsigned char>(c)) != 0 || c == '_';
601	  };
602	  if (!ok_first(vehicle_id[0])) return false;
603	  for (const char c : vehicle_id) {
604	    if (std::isalnum(static_cast<unsigned char>(c)) == 0 && c != '_') return false;
605	  }
606	  return true;
607	}
