613	std::string Vda5050GatewayNode::MqttTopic(const std::string& manufacturer,
614	                                          const std::string& vehicle_id,
615	                                          const std::string& leaf) const {
616	  return TopicBase() + "/" + manufacturer + "/" + vehicle_id + "/" + leaf;
617	}
618	
619	std::string Vda5050GatewayNode::BuildGatewayConnectionJson(const std::string& state) const {
620	  const std::string vda_version = (protocol_version_ == "v3") ? "3.0.0" : "2.0.0";
621	  std::ostringstream ss;
622	  ss << "{\"headerId\":" << g_connection_header_id.fetch_add(1, std::memory_order_relaxed)
623	     << ",\"timestamp\":\"" << CurrentIsoTimestampUtc() << "\","
624	     << "\"version\":\"" << vda_version << "\","
625	     << "\"manufacturer\":\"" << EscapeJsonString(manufacturer_) << "\","
626	     << "\"serialNumber\":\"" << EscapeJsonString(serial_number_) << "\","
627	     << "\"connectionState\":\"" << EscapeJsonString(state) << "\"}";
628	  return ss.str();
629	}
