      // 订阅已丢失且无任何错误信号。connected 回调（含首连与每次重连）只置位标志，
      // 补订阅由执行器线程完成——回调线程内对 SUBACK token wait() 会死锁。
      client_->set_connected_handler([this](const std::string& /*cause*/) {
